//! Decoding and rendering tests on tests/media (generated by
//! tools/gen-test-media.sh): every frame is a flat grey whose level encodes
//! the frame number (consecutive frames differ by 7 levels), so a single
//! pixel tells which frame was decoded.

use std::path::{Path, PathBuf};

use fs_audio::{PcmBuffer, Spectrogram, SpectrumConfig};
use fs_core::vfr::{Framerate, TimeType};
use fs_media::{Audio, SubtitleRenderer, Video, list_tracks};

fn media(name: &str) -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../../tests/media")
        .join(name)
}

/// Grey level of frame `n` after decoding to RGB: the generator draws
/// `16 + (n*7 mod 220)` in full-range grey, which round-trips through the
/// limited-range YUV encode.
fn expected_level(n: i64) -> f64 {
    (16 + (n * 7) % 220) as f64
}

fn check_frame(v: &mut Video, n: i64) {
    let px = v.frame(n).unwrap();
    let mid = (v.height() / 2 * v.width() + v.width() / 2) * 4;
    let got = px[mid] as f64;
    assert!(
        (got - expected_level(n)).abs() <= 3.0,
        "frame {n}: level {got}, expected {:.1}",
        expected_level(n)
    );
    assert_eq!(px[mid + 3], 255);
}

#[test]
fn tracks() {
    let t = list_tracks(&media("cfr.mkv")).unwrap();
    assert_eq!(t.len(), 2);
    assert_eq!((t[0].kind.as_str(), t[0].codec.as_str()), ("video", "h264"));
    assert_eq!((t[1].kind.as_str(), t[1].codec.as_str()), ("audio", "flac"));
}

#[test]
fn frame_exact_random_access() {
    let cache = tempfile::tempdir().unwrap();
    let mut calls = 0;
    let mut v = Video::open(&media("cfr.mkv"), -1, Some(cache.path()), |_, _| {
        calls += 1;
        true
    })
    .unwrap();
    assert!(calls > 0, "indexing reports progress");
    let p = v.props().clone();
    assert_eq!((p.width, p.height, p.num_frames), (320, 240, 240));
    assert_eq!((p.fps_num, p.fps_den), (24000, 1001));
    assert_eq!(p.pixel_format, "yuv420p");
    assert_eq!(v.keyframes(), &[0, 48, 96, 144, 192]);
    // backwards, across keyframes, around GOP boundaries, repeated
    for n in [
        239, 0, 100, 47, 48, 49, 200, 1, 150, 99, 239, 238, 0, 191, 192, 120,
    ] {
        check_frame(&mut v, n);
    }
    assert!(!v.linear_decoding());
    assert!(!v.is_vfr());
    let fr = v.framerate();
    assert_eq!(
        fr.frame_at_time(v.timestamps_ms()[100], TimeType::Exact),
        100
    );

    // the index is reused: reopening does not decode the track again
    let mut calls2 = 0;
    let mut v2 = Video::open(&media("cfr.mkv"), -1, Some(cache.path()), |_, _| {
        calls2 += 1;
        true
    })
    .unwrap();
    assert_eq!(v2.timestamps_ms(), v.timestamps_ms());
    check_frame(&mut v2, 77);
}

#[test]
fn cancelled_indexing_is_an_error() {
    let r = Video::open(&media("cfr.mkv"), -1, None, |_, _| false);
    assert!(r.is_err());
}

#[test]
fn vfr_timestamps_match_timecodes() {
    let mut v = Video::open(&media("vfr.mkv"), -1, None, |_, _| true).unwrap();
    let tc =
        Framerate::parse_timecodes(&std::fs::read_to_string(media("vfr-timecodes.txt")).unwrap())
            .unwrap();
    assert_eq!(v.num_frames(), 240);
    for (n, &t) in v.timestamps_ms().iter().enumerate() {
        let want = tc.time_at_frame(n as i64, TimeType::Exact);
        assert!((t - want).abs() <= 1, "frame {n}: {t} vs {want}");
    }
    let fr = v.framerate();
    assert!(v.is_vfr() && fr.is_vfr());
    for n in [0, 59, 60, 61, 179, 180, 239] {
        let t = tc.time_at_frame(n, TimeType::Start);
        assert_eq!(fr.frame_at_time(t, TimeType::Start), n, "frame {n}");
    }
    for n in [239, 60, 0, 181] {
        check_frame(&mut v, n);
    }
}

#[test]
fn audio_is_sample_exact() {
    let a = Audio::open(&media("cfr.mkv"), -1, None, |_, _| true).unwrap();
    let p = *a.props();
    assert_eq!((p.sample_rate, p.channels), (48000, 2));
    assert_eq!(p.num_samples, 480_480);
    // the same range read after seeks from both directions is identical
    let read = |s: i64| {
        let mut b = vec![0f32; 2048];
        a.read(s, &mut b).unwrap();
        b
    };
    let first = read(250_000);
    let _ = read(470_000);
    assert_eq!(read(250_000), first);
    let _ = read(0);
    assert_eq!(read(250_000), first);
    // past the end is silence
    assert!(read(480_480).iter().all(|&x| x == 0.0));

    // left 1 kHz + right 500 Hz, downmixed: both tones in the spectrum
    let pcm = PcmBuffer::load(&a, |_, _| true).unwrap();
    assert_eq!(pcm.len(), 480_480);
    let sp = Spectrogram::new(
        pcm,
        SpectrumConfig {
            fft_log2: 12,
            ..Default::default()
        },
    );
    let col = sp.column(100);
    let mut bins: Vec<usize> = (0..sp.bins()).collect();
    bins.sort_by(|&x, &y| col[y].total_cmp(&col[x]));
    let top: Vec<f32> = bins.iter().take(6).map(|&b| sp.bin_hz(b)).collect();
    assert!(top.iter().any(|f| (f - 1000.0).abs() < 20.0), "{top:?}");
    assert!(top.iter().any(|f| (f - 500.0).abs() < 20.0), "{top:?}");
}

#[test]
fn libass_renders_onto_frames() {
    let mut v = Video::open(&media("cfr.mkv"), -1, None, |_, _| true).unwrap();
    let (w, h) = (v.width(), v.height());
    let mut r = SubtitleRenderer::new().unwrap();
    r.set_script(
        "[Script Info]\nScriptType: v4.00+\nPlayResX: 320\nPlayResY: 240\n\n[V4+ Styles]\n\
         Format: Name, Fontname, Fontsize, PrimaryColour, SecondaryColour, OutlineColour, BackColour, Bold, Italic, Underline, StrikeOut, ScaleX, ScaleY, Spacing, Angle, BorderStyle, Outline, Shadow, Alignment, MarginL, MarginR, MarginV, Encoding\n\
         Style: Default,Arial,40,&H00FFFFFF,&H000000FF,&H00000000,&H00000000,0,0,0,0,100,100,0,0,1,2,0,2,10,10,10,1\n\n\
         [Events]\nFormat: Layer, Start, End, Style, Name, MarginL, MarginR, MarginV, Effect, Text\n\
         Dialogue: 0,0:00:00.00,0:00:05.00,Default,,0,0,0,,{\\an7\\pos(0,0)\\bord0\\1c&H0000FF&\\p1}m 0 0 l 100 0 100 100 0 100\n\
         Dialogue: 0,0:00:00.00,0:00:05.00,Default,,0,0,0,,Test\n",
    )
    .unwrap();
    let mut frame = v.frame(24).unwrap();
    assert!(r.blend(1000, w, h, (w, h), &mut frame).unwrap());
    let px = |f: &[u8], x: usize, y: usize| f[(y * w + x) * 4..(y * w + x) * 4 + 4].to_vec();
    assert_eq!(px(&frame, 50, 50), vec![255, 0, 0, 255]);
    // text was drawn somewhere in the bottom third
    let grey = expected_level(24).round() as i32;
    let changed = (h * 2 / 3..h)
        .flat_map(|y| (0..w).map(move |x| (x, y)))
        .filter(|&(x, y)| (px(&frame, x, y)[0] as i32 - grey).abs() > 30)
        .count();
    assert!(changed > 50, "{changed}");

    // overlay: premultiplied, transparent where nothing is drawn; nothing after 5 s
    let mut ov = vec![0u8; w * h * 4];
    assert!(r.overlay(1000, w, h, (w, h), &mut ov).unwrap());
    assert_eq!(px(&ov, 50, 50), vec![255, 0, 0, 255]);
    assert_eq!(px(&ov, 200, 20), vec![0, 0, 0, 0]);
    assert!(!r.overlay(6000, w, h, (w, h), &mut ov).unwrap());
    assert!(ov.iter().all(|&b| b == 0));
}

#[test]
fn embedded_subtitles() {
    let path = media("subs.mkv");
    let t = fs_media::subtitle_tracks(&path).unwrap();
    let kinds: Vec<_> = t
        .iter()
        .map(|t| (t.index, t.codec.as_str(), t.language.as_str()))
        .collect();
    assert_eq!(kinds, [(0, "ass", "pol"), (1, "subrip", "eng")]);

    assert_eq!(
        fs_media::chapters(&path).unwrap(),
        [(0, "Początek".to_owned()), (1500, String::new())]
    );
    assert!(fs_media::chapters(&media("cfr.mkv")).unwrap().is_empty());

    let (ass, ext) = fs_media::extract_subtitles(&path, 0).unwrap();
    assert_eq!(ext, "ass");
    let doc = fs_core::Document::parse(&ass);
    assert_eq!(doc.info("PlayResX"), Some("640"));
    let ev: Vec<_> = doc
        .events()
        .iter()
        .map(|e| &e.event)
        .map(|e| (e.layer, e.start.ms(), e.end.ms(), e.text.as_ref()))
        .collect();
    // file order (ReadOrder), not time order; commas in the text survive
    assert_eq!(
        ev,
        [
            (1, 2000, 3500, r"{\i1}Druga, z przecinkiem{\i0}"),
            (0, 500, 1250, r"Pierwsza\Nlinia"),
        ]
    );

    let (srt, ext) = fs_media::extract_subtitles(&path, 1).unwrap();
    assert_eq!(ext, "srt");
    assert!(
        srt.starts_with(
            "1\n00:00:00,500 --> 00:00:01,250\nFirst\n\n2\n00:00:02,000 --> 00:00:03,500\n"
        ),
        "{srt}"
    );
    assert!(fs_media::extract_subtitles(&media("cfr.mkv"), 0).is_err());
}
